import{_ as o,C as s,o as i,c as n,j as t,a as r,E as h,a6 as l}from"./chunks/framework.CCKCzdWs.js";const d="/screenshots/picker-runs-ci-held.png",k=JSON.parse(`{"title":"Hold a failing CI test","description":"A CI test that fails while someone who may control the project's runs watches its worker waits at its failure, its page open for Inspect, until Let it go or the project's longest hold: off by default, its result unchanged.","frontmatter":{"title":"Hold a failing CI test","description":"A CI test that fails while someone who may control the project's runs watches its worker waits at its failure, its page open for Inspect, until Let it go or the project's longest hold: off by default, its result unchanged.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/hold-ci-failure.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/hold-ci-failure.html"}],["meta",{"property":"og:title","content":"Hold a failing CI test | Piwi for Playwright"}],["meta",{"property":"og:description","content":"A CI test that fails while someone who may control the project's runs watches its worker waits at its failure, its page open for Inspect, until Let it go or the project's longest hold: off by default, its result unchanged."}]]},"headers":[],"relativePath":"features/hold-ci-failure.md","filePath":"features/hold-ci-failure.md","lastUpdated":1795612163000}`),c={name:"features/hold-ci-failure.md"};function p(w,e,u,g,f,m){const a=s("Needs");return i(),n("div",null,[e[0]||(e[0]=t("h1",{id:"hold-a-failing-ci-test",tabindex:"-1"},[r("Hold a failing CI test "),t("a",{class:"header-anchor",href:"#hold-a-failing-ci-test","aria-label":'Permalink to "Hold a failing CI test"'},"​")],-1)),h(a,{reporter:"",fixtures:""}),e[1]||(e[1]=l('<p>A CI test that fails is gone a second later: its page closes before anyone can look at it. With this setting on, a CI test that fails while a Maintainer or a Project admin watches its worker in the <a href="./live-view.html">live view</a> waits at its failure, its page open, so they can <a href="./live-inspect.html">inspect</a> the page as it failed, read its events and text, and pick the locator it should have used. <strong>Let it go</strong> ends the wait; the test then ends as it failed.</p><h2 id="turn-it-on" tabindex="-1">Turn it on <a class="header-anchor" href="#turn-it-on" aria-label="Permalink to &quot;Turn it on&quot;">​</a></h2><p>A Project admin turns on <strong>Hold a failing CI test for its controllers</strong> in <strong>Project → Settings → Live view</strong>, with the project&#39;s live view on, and sets the <strong>Longest hold</strong>: 1 to 15 minutes, 5 by default. It is off in every project. It needs <code>@piwitests/reporter</code> 0.75.0 or later: an older one never holds, and gets no <strong>Let it go</strong>. With it on, the same people may also <a href="./pause-ci-test.html">pause a CI test</a> they watch, once a Project admin turns that on too.</p><p>The CI workers of the runs going on hear the change at once: turned off, a test that is held goes on.</p><h2 id="when-a-test-is-held" tabindex="-1">When a test is held <a class="header-anchor" href="#when-a-test-is-held" aria-label="Permalink to &quot;When a test is held&quot;">​</a></h2><p>A CI test is held only when all of these stand as it fails:</p><ul><li>the project&#39;s setting is on;</li><li>someone with the <code>run:control</code> permission on the project (a Maintainer or a Project admin: <a href="/operate/project-access.html#what-each-role-can-do">roles</a>) watches that worker&#39;s lane in full: in the run page&#39;s lane panel, in an <a href="./editor-ci-runs.html#a-failure-held-for-you">editor&#39;s worker view</a>, or in <a href="./runs-window.html">Piwi Picker&#39;s Runs window</a>, each with that person&#39;s sign-in or key. A tile of <a href="./watch-all.html">Watch all</a> does not count, nor does a Viewer or a Contributor watching;</li><li>the test failed or timed out, and was not expected to.</li></ul><p>With authentication off, everyone who opens the run may control it, so anyone watching counts. Who may control the run is read as a watch opens and again at each change of it (another worker, the panel&#39;s size, its layers): a role taken away counts from then.</p><p>The page held is the one the test used last: the <code>page</code> fixture&#39;s, or one it opened itself (<code>browser.newPage()</code>, a page a <code>beforeAll</code> hook opened).</p><p>A test that fails while nobody who may control the run watches goes on at once, as it always did: a wait nobody looks at only costs CI minutes.</p><h2 id="while-it-is-held" tabindex="-1">While it is held <a class="header-anchor" href="#while-it-is-held" aria-label="Permalink to &quot;While it is held&quot;">​</a></h2><p>The test&#39;s row and its lane panel say <strong>Failed, held at its line</strong>, then for whom and until when: <strong>Held for Ana · until 12:05</strong>, naming the people watching it as it failed. The lane panel shows the failure and its place, and the live view goes on as for any watched test: the image, the call&#39;s log, <a href="./live-view-layers.html">page events, text and filmstrip</a>, and <a href="./live-inspect.html">Inspect</a> on the failing page. Nothing reaches the page: no click, no key, no code.</p><p>The test&#39;s own timeout stops while it waits, as at a breakpoint, so Playwright does not fail the wait itself. <strong>The CI job&#39;s own timeout still runs</strong>: the lane panel says so beside the hold. A job that reaches its timeout during a hold fails as it would have, later.</p><h3 id="where-it-shows" tabindex="-1">Where it shows <a class="header-anchor" href="#where-it-shows" aria-label="Permalink to &quot;Where it shows&quot;">​</a></h3><p>Every surface that watches the lane shows the hold in the same words: the run page&#39;s lane panel, VS Code&#39;s worker panel, the JetBrains <strong>Worker</strong> tab and the Runs window&#39;s CI run, whose test list marks the lane <strong>Failed, held at its line</strong> too. <strong>Let it go</strong> shows on a surface whose own watch of the lane counts as a controller&#39;s: the instance says so to that watch as it opens, so an editor or Piwi Picker connected with a Maintainer&#39;s key offers it, and one connected with a Viewer&#39;s key shows the hold without it. A refusal is said in the instance&#39;s words.</p><figure><img src="'+d+'" width="488" alt="The Runs window watching worker 2 of CI run #78: the test list marks it Failed, held at its line, and above its live page a box says Failed, held at its line, Held for Ana until a time, the expected and received text, tests/checkout.spec.ts:42, The CI job’s own timeout still runs, and a Let it go button"><figcaption>A held CI failure in the Runs window, with Let it go.</figcaption></figure><p>The run&#39;s log says that the test is held, and until when, in UTC:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[piwi] The test failed at tests/checkout.spec.ts:42: held for the people watching it on the run page, until 12:05:00 UTC at the latest.</span></span></code></pre></div><h2 id="when-it-ends" tabindex="-1">When it ends <a class="header-anchor" href="#when-it-ends" aria-label="Permalink to &quot;When it ends&quot;">​</a></h2><p>The hold ends at the first of:</p><ul><li><strong>Let it go</strong>, on a surface watching the lane, which only someone with <code>run:control</code> sees;</li><li>the longest hold the project set. A new length set during a hold applies to it: the hold ends that long after it began, at once when that is past;</li><li>nobody with <code>run:control</code> watching the lane in full any more: the last one closed the panel or moved to another lane. A Runs window hidden or minimized lets go of its watch, so it stops counting;</li><li>the project&#39;s setting turned off, or the run&#39;s live view ending (the run ended or interrupted, the project&#39;s live view turned off).</li></ul><p>The test then tears down as it would have: its result, its error and its trace are those of the failure, and its <code>piwi-pauses</code> attachment records the hold. Its reported duration leaves the wait out.</p><p><strong>Let it go</strong> is logged by the instance at info level, with the run, the worker and who asked. Nothing is stored.</p><h2 id="what-it-costs-and-what-it-never-does" tabindex="-1">What it costs, and what it never does <a class="header-anchor" href="#what-it-costs-and-what-it-never-does" aria-label="Permalink to &quot;What it costs, and what it never does&quot;">​</a></h2><ul><li><strong>CI minutes.</strong> A held test holds its CI job&#39;s runner for the longest hold at most, each time. One lane waits; the run&#39;s other workers go on.</li><li><strong>No new reach.</strong> The worker already holds its live view stream to the instance; nothing listens on the CI machine. The instance checks the setting and the permission of the person who asks, and the worker takes <strong>Let it go</strong> only on its own stream, and only while its project&#39;s setting is on.</li><li><strong>No input.</strong> The page takes no click, key or text from a viewer, and nothing is run in it: the CI page may be signed in to real systems.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./pause-ci-test.html">Pause a CI test</a>: pause, resume and end a CI test you watch</li><li><a href="./live-view.html">Live view of a run</a>: watching a CI run&#39;s workers</li><li><a href="./live-inspect.html">Inspect a worker&#39;s page</a>: the page at each call, with the locator picker</li><li><a href="./live-view-layers.html">Page events, text and filmstrip</a>: what the page said beside the image</li><li><a href="/operate/project-access.html#what-each-role-can-do">Who can do what</a>: the <code>run:control</code> permission</li></ul>',27))])}const y=o(c,[["render",p]]);export{k as __pageData,y as default};
